use ark_bn254::{Bn254, Fr};
use ark_circom::CircomReduction;
use ark_groth16::{Groth16, Proof, VerifyingKey};
use ark_serialize::CanonicalDeserialize;
use ark_snark::SNARK;

/// Verify a Groth16/BN254 proof generated by a circom circuit (snarkjs compatible).
///
/// `proof`         – arkworks `Proof<Bn254>`, constructed from snarkjs pi_a/pi_b/pi_c
/// `public_inputs` – public signals as `Fr` field elements, in the same order as snarkjs public.json
pub fn verify(
    proof: &Proof<Bn254>,
    public_inputs: &[Fr],
) -> Result<bool, <Groth16<Bn254, CircomReduction> as SNARK<Fr>>::Error> {
    Groth16::<Bn254, CircomReduction>::verify(&embedded_vk(), public_inputs, proof)
}

